    'friuli-venezia-giulia': function(i){ return path('M90 160 L270 160 L250 300 C250 312 110 312 110 300 Z',W)+path('M90 160 L270 160 L266 190 L94 190 Z',i[0])+path('M270 190 C330 190 330 260 262 262',W,'fill="none" stroke="'+W+'" stroke-width="18"')+'<ellipse cx="180" cy="320" rx="130" ry="20" fill="'+W+'"/>'+path('M140 150 C130 120 150 100 140 70 M190 150 C180 120 200 100 190 70',W,'fill="none" stroke="'+mix(i[2],W,.5)+'" stroke-width="8" stroke-linecap="round"')+'<ellipse cx="180" cy="172" rx="78" ry="10" fill="'+i[2]+'"/>'; },
